function setFile(file){
 const err=$('#dropError'),clearErr=()=>{if(err){err.textContent='';err.classList.add('hidden')}$('#dropzone').classList.remove('has-error')};
 if(file&&(!file.name.toLowerCase().endsWith('.docx')||file.size>50*1024*1024)){const tooBig=file.size>50*1024*1024,isDoc=/\.doc$/i.test(file.name),msg=tooBig?'Dokument je veći od 50 MB.':isDoc?'Stariji .doc format nije podržan. U Wordu odaberi Datoteka pa Spremi kao i odaberi .docx.':'Odaberi Word dokument u .docx formatu.';$('#fileInput').value='';if(err){err.textContent=msg;err.classList.remove('hidden')}$('#dropzone').classList.add('has-error');toast(msg);return}
 clearErr();$('#detectBadge')?.classList.add('hidden');
 selectedDocx=file||null;$('#dropEmpty').classList.toggle('hidden',!!file);$('#selectedFile').classList.toggle('hidden',!file);$('#dropzone').classList.toggle('has-file',!!file);$('#analyzeBtn').disabled=!file;$('#demoBtn')?.classList.toggle('hidden',!!file);
 if(file){$('#selectedName').textContent=file.name;$('#selectedMeta').textContent=`${(file.size/1024/1024).toFixed(2)} MB · spremno za lokalnu analizu`;applyDetectedContext(file);updateQuickStats(file)}else $('#fileInput').value='';
}
// Feature 4: auto-detekcija fakulteta/studija/razine s uploada. Cisto citanje parsera (bez izmjene
// enginea): iz naslovnice + core naslova heuristicki pogadja kombinaciju i prretpopuni izbornike.
// Nikad ne blokira analizu; ako nista ne prepozna, ostavlja postojeci odabir. Korisnik moze ispraviti.
let _detectToken=0,_statsToken=0,_analyzeToken=0;
// Brzi peek rijeci/stranica iz app.xml (ne dira analyzeDocx); token guard protiv zastarjelog updatea.
async function updateQuickStats(file){const token=++_statsToken,s=await docxQuickStats(file);if(token!==_statsToken||selectedDocx!==file||!s)return;const bits=[];if(s.words)bits.push(`${fmt(s.words)} riječi`);if(s.pages)bits.push(`${s.pages} str.`);if(bits.length&&$('#selectedMeta'))$('#selectedMeta').textContent=`${(file.size/1024/1024).toFixed(2)} MB · ${bits.join(' · ')}`}
async function detectDocxContext(file){
 try{
  const zip=new ZipReader(await file.arrayBuffer());const xml=await zip.text('word/document.xml');if(!xml)return null;
  const doc=parseXml(xml,'Detekcija konteksta'),paras=els(doc,'w:p').map(paragraphText).map(x=>x.trim()).filter(Boolean).slice(0,80);
  let coreTitle='';try{const c=await zip.text('docProps/core.xml');if(c)coreTitle=textOf(first(parseXml(c,'DOCX core'),'dc:title'))||''}catch(e){}
  const n=normalize(paras.join(' ')+' '+coreTitle);if(!n)return null;
  const units=(ZAGREB_CATALOG.find(g=>g.id==='unizg')||{units:[]}).units;
  let unit=null,best=0;for(const u of units){const key=normalize(u.name);if(key.length>=6&&key.length>best&&n.includes(key)){unit=u;best=key.length}}
  if(!unit)return null;
  const wtRules=[['doctoral',/doktorsk|disertacij/],['specialist',/specijalisticki/],['graduate',/diplomskirad/],['final',/zavrsnirad/],['seminar',/seminarskirad/]];
  let workType=null;for(const[wt,re]of wtRules)if(re.test(n)){workType=wt;break}
  let program=null,pbest=0;for(const p of(unit.programs||[])){if(/^Opći/.test(p)||/studij/i.test(p))continue;const key=normalize(p);if(key.length>=5&&key.length>pbest&&n.includes(key)){program=p;pbest=key.length}}
  return{unitId:unit.id,unitName:unit.name,program,workType};
 }catch(e){return null}
}
async function applyDetectedContext(file){
 const token=++_detectToken,ctx=await detectDocxContext(file);
 if(token!==_detectToken||!ctx)return;
 setOptionIfExists($('#institutionSelect'),'unizg');populateUnits();
 setOptionIfExists($('#unitSelect'),ctx.unitId);populatePrograms();
 if(ctx.program)setOptionIfExists($('#programSelect'),ctx.program);
 autoSelectWorkType();if(ctx.workType)setOptionIfExists($('#workType'),ctx.workType);
 syncProfileContext();savePreferences();
 const parts=[ctx.unitName];if(ctx.program)parts.push(ctx.program);if(ctx.workType)parts.push(WORK_TYPE_LABELS[ctx.workType]||ctx.workType);
 const badge=$('#detectBadge');if(badge){badge.innerHTML=`<i data-lucide="info"></i> Prepoznato iz dokumenta: ${escapeHtml(parts.join(' · '))}. Provjeri i ispravi po potrebi.`;badge.classList.remove('hidden');window.__lektaIcons?.()}
 toast('Prepoznato iz dokumenta: '+parts.join(' · ')+'.');
}
function setAuxFile(kind,file){
 const isPdf=kind==='pdf',isAv=kind==='av',max=isPdf?100*1024*1024:isAv?8*1024*1024*1024:25*1024*1024,ext=isPdf?'.pdf':isAv?null:'.docx';
 if(file&&((ext&&!file.name.toLowerCase().endsWith(ext))||file.size>max)){toast(file&&file.size>max?`Datoteka je veća od ${Math.round(max/1024/1024)} MB.`:`Odaberi datoteku u ${ext} formatu.`);return}
 if(isPdf){selectedPdf=file||null;currentPdfAudit=null;$('#pdfInput').value=file?'':''}
 else if(isAv){selectedAvFile=file||null;$('#avInput').value=file?'':''}
 else{selectedMetadataDocx=file||null;currentMetadataAudit=null;$('#metadataInput').value=file?'':''}
 updatePackageUi();
}
function currentSubmissionPhase(){return $('#submissionPhase')?.value||'document'}
function currentFpzgCohort(){return $('#fpzgCohort')?.value||'current'}
function currentFpzgDeadlineId(){return $('#fpzgDeadline')?.value||null}
function currentDefinitionId(){return findVerifiedDefinition()?.id||null}
function isFpzgAvProfile(){return $('#unitSelect')?.value==='fpzg'&&currentDefinitionId()==='fpzg-novinarstvo-zavrsni-av'}
function fpzgScheduleType(){const id=currentDefinitionId();if(['fpzg-politologija-zavrsni','fpzg-novinarstvo-zavrsni-tekst','fpzg-novinarstvo-zavrsni-av'].includes(id))return'final';if(['fpzg-politologija-diplomski','fpzg-nacionalna-sigurnost-diplomski','fpzg-novinarstvo-diplomski'].includes(id))return'graduate';return null}
function hrDate(value,withTime=false){if(!value)return'—';const d=new Date(value.length===10?value+'T12:00:00':value);return new Intl.DateTimeFormat('hr-HR',{day:'2-digit',month:'2-digit',year:'numeric',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(d)}
function dateRange(a,b){return`${hrDate(a)} do ${hrDate(b)}`}
function deadlineState(entry){const now=Date.now(),start=new Date((entry.defenseStart||entry.start)+'T00:00:00').getTime(),end=new Date((entry.defenseEnd||entry.end)+'T23:59:59').getTime(),cutoff=entry.cutoff?new Date(entry.cutoff).getTime():null;if(now>end)return{key:'closed',label:'rok završen'};if(now>=start&&now<=end)return{key:'active',label:'obrane u tijeku'};if(cutoff&&now>cutoff)return{key:'cutoff',label:'rok prijave prošao'};return{key:'upcoming',label:'nadolazeći rok'}}
function fpzgDeadlineEntries(type=fpzgScheduleType(),cohort=currentFpzgCohort()){if(type==='final')return FPZG_SUBMISSION_CALENDAR.final.windows.filter(x=>x.cohorts.includes(cohort));if(type==='graduate')return FPZG_SUBMISSION_CALENDAR.graduate.sessions;return[]}
function populateFpzgDeadlineOptions(){const type=fpzgScheduleType(),show=!!type&&currentSubmissionPhase()!=='document',cohortField=$('#fpzgCohortField'),deadlineField=$('#fpzgDeadlineField'),select=$('#fpzgDeadline');cohortField?.classList.toggle('hidden',!(show&&type==='final'));deadlineField?.classList.toggle('hidden',!show);$('#fpzgPhaseHint')?.classList.toggle('hidden',!(!!type&&!show));if(!show||!select)return;const previous=select.value,entries=fpzgDeadlineEntries(type);select.innerHTML=entries.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.label)} · ${escapeHtml(dateRange(x.defenseStart||x.start,x.defenseEnd||x.end))}</option>`).join('');if(entries.some(x=>x.id===previous))select.value=previous;else{const next=entries.find(x=>new Date((x.defenseEnd||x.end)+'T23:59:59').getTime()>=Date.now())||entries.at(-1);if(next)select.value=next.id}const help=$('#fpzgDeadlineHelp');if(help)help.textContent=type==='final'?'Datum obrane mora biti radni dan unutar odabranog razdoblja, a prijava najmanje tri radna dana ranije.':'Odabrani rok određuje krajnji datum D2 obrasca, uvezanog rada i dokumentacije te razdoblje obrane.'}
