function safeStorageGet(key,fallback=null){try{const raw=localStorage.getItem(key);if(raw)return JSON.parse(raw)}catch(e){}return SESSION_MEMORY.has(key)?structuredClone(SESSION_MEMORY.get(key)):fallback}
function safeStorageSet(key,value){SESSION_MEMORY.set(key,structuredClone(value));try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){return false}}
function optionExists(select,value){return !!select&&[...select.options].some(o=>o.value===value)}
function setOptionIfExists(select,value){if(value!=null&&optionExists(select,value))select.value=value}
function savePreferences(){const p={institution:$('#institutionSelect')?.value,unit:$('#unitSelect')?.value,program:$('#programSelect')?.value,workType:$('#workType')?.value,variant:$('#workVariant')?.value,department:$('#departmentSelect')?.value,methodology:$('#methodologySelect')?.value,citation:$('#citationStyle')?.value,language:$('#docLanguage')?.value,strictness:$('#strictness')?.value,submissionPhase:$('#submissionPhase')?.value,fpzgCohort:$('#fpzgCohort')?.value,fpzgDeadline:$('#fpzgDeadline')?.value,mentorOverride:!!$('#mentorOverride')?.checked,customFont:$('#customFont')?.value,customSize:$('#customSize')?.value,customSpacing:$('#customSpacing')?.value,customMargin:$('#customMargin')?.value};safeStorageSet(STORAGE_KEYS.preferences,p)}
function restorePreferences(){const p=safeStorageGet(STORAGE_KEYS.preferences);if(!p)return;setOptionIfExists($('#institutionSelect'),p.institution);populateUnits();setOptionIfExists($('#unitSelect'),p.unit);populatePrograms();setOptionIfExists($('#programSelect'),p.program);setOptionIfExists($('#workType'),p.workType);populateVariants();setOptionIfExists($('#workVariant'),p.variant);populateDepartments();setOptionIfExists($('#departmentSelect'),p.department);populateMethodology();setOptionIfExists($('#methodologySelect'),p.methodology);setOptionIfExists($('#citationStyle'),p.citation);setOptionIfExists($('#docLanguage'),p.language);setOptionIfExists($('#strictness'),p.strictness);setOptionIfExists($('#submissionPhase'),p.submissionPhase);updateSubmissionContextFields();setOptionIfExists($('#fpzgCohort'),p.fpzgCohort);populateFpzgDeadlineOptions();setOptionIfExists($('#fpzgDeadline'),p.fpzgDeadline);$('#mentorOverride').checked=!!p.mentorOverride;$('#customSettings').classList.toggle('hidden',!p.mentorOverride);if(p.customFont)$('#customFont').value=p.customFont;if(p.customSize)$('#customSize').value=p.customSize;if(p.customSpacing)$('#customSpacing').value=p.customSpacing;if(p.customMargin)$('#customMargin').value=p.customMargin}
function loadProductionConfig(){const saved=safeStorageGet(STORAGE_KEYS.production,{});return{...structuredClone(DEFAULT_PRODUCTION_CONFIG),...(saved||{}),paymentLinks:{...DEFAULT_PRODUCTION_CONFIG.paymentLinks,...(saved?.paymentLinks||{})}}}
function productionStatus(){const links=Object.values(productionConfig?.paymentLinks||{}).filter(Boolean).length,endpoint=String(productionConfig?.orderEndpoint||'').trim();return{active:!!productionConfig?.enabled&&!!endpoint,links,endpoint,provider:productionConfig?.paymentProvider||'stripe'}}
function renderProductionState(){const el=$('#productionState');if(!el)return;const st=productionStatus(),max=Math.round((productionConfig.uploadMaxBytes||0)/1024/1024);el.className=`production-state ${st.active?'ready':'warn'}`;el.innerHTML=st.active?`<strong>Produkcijska predaja je aktivna</strong><span class="provider-pill">${escapeHtml(st.provider)}</span> Obrazac se šalje na konfigurirani endpoint. Dokument do ${max} MB može biti uključen u narudžbu.${st.links?` Dostupna su ${st.links} payment linka.`:' Payment linkovi još nisu uneseni.'}`:`<strong>Testni fallback — slanje nije aktivirano</strong>Narudžba će se spremiti kao lokalni JSON bez prijenosa dokumenta. Otvori aplikaciju s <code>?setup=1</code> za testiranje ili uredi <code>DEFAULT_PRODUCTION_CONFIG</code> prije objave.`}
function selectedOrderFile(){return $('#orderDocument')?.files?.[0]||selectedDocx||null}
function updateOrderFileMeta(){const f=selectedOrderFile(),el=$('#orderFileMeta'),max=Math.round((productionConfig.uploadMaxBytes||0)/1024/1024);if(!el)return;el.textContent=f?`${f.name} · ${(f.size/1024/1024).toFixed(2)} MB · ${f.size<=(productionConfig.uploadMaxBytes||0)?'spremno za slanje':'preveliko za konfigurirani kanal'}`:`Nije odabran dokument. Možeš poslati narudžbu bez datoteke i naknadno dogovoriti siguran kanal. Najviše ${max} MB.`}
function makeOrderId(){return`TR-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Math.random().toString(36).slice(2,8).toUpperCase()}`}
function setOrderStatus(type,html){const el=$('#orderStatus');el.className=`order-status ${type}`;el.innerHTML=html;el.classList.remove('hidden')}
function clearOrderStatus(){$('#orderStatus')?.classList.add('hidden');if($('#orderStatus'))$('#orderStatus').innerHTML=''}
function sanitizeEventData(data){const allowed={};for(const[k,v]of Object.entries(data||{})){if(['event','package','profileId','workType','scoreBand','provider','source'].includes(k)&&['string','number','boolean'].includes(typeof v))allowed[k]=v}return allowed}
async function trackEvent(event,data={}){if(!productionConfig?.analyticsEndpoint||safeStorageGet(STORAGE_KEYS.analyticsConsent)!=='granted')return false;try{await fetch(productionConfig.analyticsEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event,version:APP_VERSION,path:location.pathname||'/',timestamp:new Date().toISOString(),...sanitizeEventData(data)}),keepalive:true});return true}catch(e){return false}}
function renderConsentBanner(force=false){const b=$('#consentBanner');if(!b)return;const configured=!!productionConfig?.analyticsEndpoint,choice=safeStorageGet(STORAGE_KEYS.analyticsConsent);b.classList.toggle('hidden',!configured||(!force&&!!choice))}
function setAnalyticsConsent(value){safeStorageSet(STORAGE_KEYS.analyticsConsent,value);$('#consentBanner')?.classList.add('hidden');toast(value==='granted'?'Anonimna analitika je dopuštena.':'Ostat će aktivne samo nužne lokalne postavke.')}
function openPrivacySettings(){if(productionConfig?.analyticsEndpoint){renderConsentBanner(true)}else openLegal('privacy')}
function legalDocuments(){const org=productionConfig.businessName||'Lekta',contact=productionConfig.contactEmail||'kontakt nije konfiguriran',controller=productionConfig.privacyController||org,days=Number(productionConfig.retentionDays)||30;return{privacy:{title:'Obavijest o privatnosti',html:`<div class="legal-meta"><strong>Verzija:</strong> ${TERMS_VERSION} · <strong>Voditelj obrade:</strong> ${escapeHtml(controller)} · <strong>Kontakt:</strong> ${escapeHtml(contact)}</div><h4>1. Lokalna automatska analiza</h4><p>Besplatna automatska provjera odvija se u pregledniku. Tekst dokumenta, sama datoteka i pronađeni problemi tada se ne šalju na poslužitelj. Lokalna povijest, ako je dostupna, sadrži samo naziv datoteke, rezultat i odabrani profil.</p><p>Ako korisnik nakon prijave e-mailom izričito zatraži <strong>puni izvještaj</strong>, na poslužitelj se šalju podaci izvedeni iz dokumenta nužni za njegovu izradu: naslov i autor rada, struktura naslova te pronađene stavke provjere. Sam tekst rada i datoteka i tada ostaju u pregledniku. Poslužitelj donosi odluku o pristupu, a te podatke koristi isključivo za izradu naručenog izvještaja.</p><h4>2. Ručna usluga</h4><p>Kada korisnik izričito pošalje narudžbu, obrađuju se ime, e-mail, rok, napomena, odabrani paket, profil analize i dokument koji je korisnik odabrao. Svrha je komunikacija, ponuda, naplata i izvršenje naručene usluge.</p><h4>3. Plaćanje i pružatelji usluga</h4><p>Podaci o kartici ne obrađuju se u Lekta sučelju, nego na hostiranoj stranici konfiguriranog payment providera. Hosting, obrazac i payment provider mogu djelovati kao izvršitelji obrade prema vlastitim uvjetima.</p><h4>4. Rok čuvanja</h4><p>Podaci narudžbe i radni dokument čuvaju se najdulje ${days} dana nakon dovršetka usluge, osim kada zakon, računovodstvene obveze ili spor zahtijevaju dulje čuvanje. Datoteke se zatim brišu ili anonimiziraju.</p><h4>5. Analitika</h4><p>Aplikacija ne učitava marketinške trackere. Opcionalni anonimni događaji korištenja šalju se samo uz privolu i samo kada je konfiguriran poseban event endpoint. Netlifyjeva poslužiteljska analitika može se zasebno uključiti na razini hostinga.</p><h4>6. Prava korisnika</h4><p>Za pristup, ispravak, brisanje, ograničenje ili prigovor obrati se na ${escapeHtml(contact)}. Prije javne objave ovaj predložak treba uskladiti sa stvarnim poslovnim subjektom, procesorima i rokovima čuvanja.</p>`},terms:{title:'Uvjeti korištenja i narudžbe',html:`<div class="legal-meta"><strong>Verzija:</strong> ${TERMS_VERSION} · <strong>Pružatelj:</strong> ${escapeHtml(org)} · <strong>Kontakt:</strong> ${escapeHtml(contact)}</div><h4>1. Predmet usluge</h4><p>Lekta pruža tehnički audit akademskog dokumenta i, kada je naručeno, ručno formatiranje ili pregled citatne i strukturne konzistentnosti. Usluga ne piše sadržaj rada umjesto korisnika i ne jamči ocjenu, prihvaćanje ili odobrenje mentora.</p><h4>2. Odgovornost korisnika</h4><p>Korisnik mora imati pravo dostaviti dokument i odgovoran je za akademsku čestitost, točnost sadržaja, autorska prava, osobne podatke u radu i konačnu provjeru službenih uputa.</p><h4>3. Narudžba i plaćanje</h4><p>Narudžba postaje operativna nakon uspješnog zaprimanja obrasca i, kada je primjenjivo, potvrđenog plaćanja. Konačni opseg, rok i cijena prikazuju se prije plaćanja ili se potvrđuju zasebnom ponudom.</p><h4>4. Rok i suradnja</h4><p>Rok ovisi o opsegu dokumenta, kvaliteti izvornog Worda i pravodobnoj dostavi svih uputa. Kašnjenje korisnika s dodatnim materijalima može pomaknuti rok.</p><h4>5. Otkaz i povrat</h4><p>Prava na otkaz, jednostrani raskid i povrat ovise o vrsti usluge, trenutku početka izvršenja i primjenjivom potrošačkom pravu. Prije početka individualne obrade korisniku treba jasno potvrditi uvjete, cijenu i eventualni zahtjev za početak izvršenja prije isteka roka za raskid.</p><h4>6. Zabranjena uporaba</h4><p>Nije dopušteno naručiti izradu lažnog rada, prikrivanje plagijata, falsificiranje podataka ili drugu akademsku prijevaru. Pružatelj može odbiti takvu narudžbu.</p><h4>7. Mjerodavna pravila</h4><p>Službene upute fakulteta, studija, kolegija i mentora uvijek imaju prednost pred automatskim profilom aplikacije. Ovaj tekst je operativni predložak i treba pravni pregled prije komercijalnog lansiranja.</p>`},disclaimer:{title:'Odricanje od odgovornosti',html:`<div class="legal-meta"><strong>Verzija:</strong> ${TERMS_VERSION}</div><h4>Tehničko pomagalo, ne službena potvrda</h4><p>Rezultat aplikacije je heuristička tehnička provjera. Nije službena potvrda fakulteta, pravno mišljenje, lektura, recenzija znanstvene kvalitete ni odluka mentora ili povjerenstva.</p><h4>Mogući lažni alarmi i propuštanja</h4><p>Word dokumenti, citatni stilovi i fakultetske iznimke mogu biti složeni. Aplikacija može označiti ispravan element ili propustiti stvarnu pogrešku. Svaki nalaz treba provjeriti u izvornom dokumentu i prema aktualnim službenim pravilima.</p><h4>Posebne upute</h4><p>Pisana uputa mentora, nositelja kolegija ili studija ima prednost. Korisnik snosi odgovornost za konačnu verziju rada, izvore, citate, istraživačku etiku i pravodobnu predaju.</p>`}}}
// Fokus u modalima (a11y): zarobi Tab unutar modala i vrati fokus na okidac pri zatvaranju.
let _modalReturnFocus=null;
function modalFocusables(el){return[...el.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetWidth||x.offsetHeight||x.getClientRects().length)}
function trapModal(el){if(!el)return;_modalReturnFocus=document.activeElement;el._trap=e=>{if(e.key!=='Tab')return;const f=modalFocusables(el);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};el.addEventListener('keydown',el._trap);setTimeout(()=>{(el.querySelector('.modal-close')||modalFocusables(el)[0])?.focus()},30)}
function releaseModal(el){if(el&&el._trap){el.removeEventListener('keydown',el._trap);el._trap=null}if(_modalReturnFocus){try{_modalReturnFocus.focus()}catch(e){}_modalReturnFocus=null}}
function openLegal(kind='privacy'){const doc=legalDocuments()[kind]||legalDocuments().privacy;$('#legalTitle').textContent=doc.title;$('#legalContent').innerHTML=doc.html;$('#legalModal').classList.remove('hidden');trapModal($('#legalModal'))}
function closeLegal(){$('#legalModal')?.classList.add('hidden');releaseModal($('#legalModal'))}
function openSetup(){const c=productionConfig;$('#setupEnabled').value=String(!!c.enabled);$('#setupProvider').value=c.paymentProvider||'stripe';$('#setupOrderEndpoint').value=c.orderEndpoint||'';$('#setupBusinessName').value=c.businessName||'';$('#setupContactEmail').value=c.contactEmail||'';$('#setupRetentionDays').value=c.retentionDays||30;$('#setupUploadMb').value=Math.round((c.uploadMaxBytes||8*1024*1024)/1024/1024);$('#setupAnalyticsEndpoint').value=c.analyticsEndpoint||'';$('#setupReportEndpoint').value=c.reportEndpoint||'';$('#setupCheckoutEndpoint').value=c.checkoutEndpoint||'';$('#setupGuaranteeEndpoint')&&($('#setupGuaranteeEndpoint').value=c.guaranteeEndpoint||'');$('#setupReportToken').value=c.reportToken||'';$('#setupSupabaseUrl')&&($('#setupSupabaseUrl').value=c.supabaseUrl||'');$('#setupSupabaseAnon')&&($('#setupSupabaseAnon').value=c.supabaseAnonKey||'');$('#setupPaymentLinks').innerHTML=PACKAGES.map(p=>`<div class="field full"><label for="setupPay-${p.id}">${escapeHtml(p.name)}</label><input class="input setup-payment" id="setupPay-${p.id}" data-package="${p.id}" value="${escapeHtml(c.paymentLinks?.[p.id]||'')}" placeholder="https://…"></div>`).join('');$('#setupModal').classList.remove('hidden');trapModal($('#setupModal'))}
function closeSetup(){$('#setupModal')?.classList.add('hidden');releaseModal($('#setupModal'))}
function readSetupConfig(){const paymentLinks={};$$('.setup-payment').forEach(x=>paymentLinks[x.dataset.package]=x.value.trim());return{...productionConfig,enabled:$('#setupEnabled').value==='true',paymentProvider:$('#setupProvider').value,orderEndpoint:$('#setupOrderEndpoint').value.trim(),businessName:$('#setupBusinessName').value.trim()||'Lekta',contactEmail:$('#setupContactEmail').value.trim(),privacyController:$('#setupBusinessName').value.trim()||'Lekta',retentionDays:Number($('#setupRetentionDays').value)||30,uploadMaxBytes:(Number($('#setupUploadMb').value)||8)*1024*1024,analyticsEndpoint:$('#setupAnalyticsEndpoint').value.trim(),reportEndpoint:$('#setupReportEndpoint').value.trim(),checkoutEndpoint:$('#setupCheckoutEndpoint').value.trim(),guaranteeEndpoint:($('#setupGuaranteeEndpoint')?.value||'').trim(),reportToken:$('#setupReportToken').value.trim(),supabaseUrl:($('#setupSupabaseUrl')?.value||'').trim(),supabaseAnonKey:($('#setupSupabaseAnon')?.value||'').trim(),paymentLinks}}
function saveSetupConfig(){productionConfig=readSetupConfig();safeStorageSet(STORAGE_KEYS.production,productionConfig);closeSetup();renderProductionState();renderConsentBanner();resetUnlockButton();void ensureRetailCatalog(true);toast('Testna produkcijska konfiguracija je spremljena u ovom pregledniku.')}
function resetSetupConfig(){safeStorageSet(STORAGE_KEYS.production,{});productionConfig=structuredClone(DEFAULT_PRODUCTION_CONFIG);openSetup();toast('Vraćene su zadane vrijednosti.')}
function exportProductionConfig(){const c=readSetupConfig();downloadBlob(JSON.stringify(c,null,2),'application/json','Lekta-production-config-v2.2.2.json')}
function buildPaymentUrl(base,email,orderId,pkg){if(!base)return'';try{const u=new URL(base,location.href);if(productionConfig.paymentProvider==='stripe'){u.searchParams.set('prefilled_email',email);u.searchParams.set('utm_source','lekta');u.searchParams.set('utm_medium','app');u.searchParams.set('utm_campaign','order');u.searchParams.set('utm_content',pkg);u.searchParams.set('utm_term',orderId)}else if(productionConfig.paymentProvider==='lemonsqueezy'){u.searchParams.set('checkout[email]',email);u.searchParams.set('checkout[custom][order_id]',orderId);u.searchParams.set('checkout[custom][package]',pkg)}else{u.searchParams.set('order_id',orderId);u.searchParams.set('email',email)}return u.toString()}catch(e){return base}}
function saveOrderReceipt(order){const arr=safeStorageGet(STORAGE_KEYS.orders,[])||[];arr.unshift({orderId:order.orderId,createdAt:order.createdAt,package:order.package?.id,status:order.status,profile:order.analysis?.profile||order.requestedProfile?.unit||null});safeStorageSet(STORAGE_KEYS.orders,arr.slice(0,10))}
function autoSelectWorkType(){const exact=exactWorkTypes();if(!exact.size)return;const current=$('#workType').value,pick=pickWorkType(exact,current);if(pick!==current&&$('#workType').querySelector('option[value="'+pick+'"]'))$('#workType').value=pick}
function exactWorkTypes(){const u=selectedUnit(),program=$('#programSelect').value;return workTypesForSelection(VERIFIED_PROFILE_REGISTRY,u.id,program)}
function updateWorkTypeSupport(){const exact=exactWorkTypes(),current=$('#workType').value;for(const o of $('#workType').options){const base=WORK_TYPE_LABELS[o.value]||o.value;o.textContent=base}/*A-lock*/const wt=$('#workType');if(isWorkTypeLocked(exact)){const only=[...exact][0];if(wt.querySelector('option[value="'+only+'"]')&&wt.value!==only)wt.value=only;wt.disabled=true}else wt.disabled=false;const help=$('#workTypeSupport');if(!help)return;const supported=[...exact].map(x=>WORK_TYPE_LABELS[x]||x);if(isWorkTypeLocked(exact)){help.className='work-support exact';help.textContent='Vrsta rada je određena odabranim studijem (zaključano).'}else if(exact.has(current)){help.className='work-support exact';help.textContent='Za ovu kombinaciju postoji poseban normativni profil.'}else{help.className='work-support generic';help.textContent=supported.length?`Odabrana vrsta koristi opću provjeru. Posebno podržano: ${supported.join(', ')}.`:'Za ovaj studij još nema posebnog profila vrste rada; koristi se transparentna opća provjera.'}}
function hashString(input){let h=2166136261;for(let i=0;i<input.length;i++){h^=input.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16).padStart(8,'0')}
function profileFingerprint(profile){const compact={version:APP_VERSION,definition:profile.definitionId||null,department:profile.department?.id||null,workType:profile.selection?.workType,citation:profile.citation,authority:profile.ruleAuthority,rules:{font:profile.font,size:profile.size,spacing:profile.spacing,margins:profile.margins,wordMin:profile.wordMin,wordMax:profile.wordMax,charMin:profile.charMin,charMax:profile.charMax,minReferences:profile.minReferences,requiredSections:profile.requiredSections?.map(x=>x.key),headingRules:profile.headingRules},sources:(profile.sources||[]).map(x=>x.url)};return`LK-${APP_VERSION}-${hashString(JSON.stringify(compact))}`}
function getAnalysisHistory(){return safeStorageGet(STORAGE_KEYS.history,[])||[]}
function saveAnalysisHistory(result){if(!result||String(result.version||'').includes('demo'))return;const ids=result.settings?.selectionIds||{};const item={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,generatedAt:result.generatedAt,fileName:result.file?.name||'Dokument',score:result.score,issueCount:result.issues?.length||0,errors:(result.issues||[]).filter(x=>x.severity==='error').length,warnings:(result.issues||[]).filter(x=>x.severity==='warning').length,profile:result.profile,fingerprint:result.details?.profileFingerprint||null,selectionIds:ids};const history=[item,...getAnalysisHistory()].slice(0,8);safeStorageSet(STORAGE_KEYS.history,history);updateHistoryBadge()}
function updateHistoryBadge(){const n=getAnalysisHistory().length;$('#historyCount').textContent=n?`(${n})`:''}
function openHistory(){renderHistory();$('#historyModal').classList.remove('hidden');trapModal($('#historyModal'))}
function closeHistory(){$('#historyModal')?.classList.add('hidden');releaseModal($('#historyModal'))}
function renderHistory(){const h=getAnalysisHistory();$('#historyList').innerHTML=h.length?h.map(x=>`<article class="history-card"><div class="history-head"><div><h4>${escapeHtml(x.fileName)}</h4><p>${escapeHtml(x.profile)}</p></div><div class="history-score">${Number.isFinite(Number(x.score))?Number(x.score):'—'}</div></div><div class="history-meta"><span>${escapeHtml(new Date(x.generatedAt).toLocaleString('hr-HR'))}</span><span>${Number(x.issueCount)||0} problema</span><span>${Number(x.errors)||0} važnih</span>${x.fingerprint?`<span>${escapeHtml(x.fingerprint)}</span>`:''}</div><div class="history-actions"><button class="btn btn-secondary btn-sm" data-history-profile="${escapeHtml(x.id)}">Učitaj profil</button><button class="btn btn-ghost btn-sm" data-history-delete="${escapeHtml(x.id)}">Ukloni</button></div></article>`).join(''):'<div class="empty">Još nema spremljenih lokalnih rezultata.</div>'}
function handleHistoryAction(e){const profileId=e.target.closest('[data-history-profile]')?.dataset.historyProfile,deleteId=e.target.closest('[data-history-delete]')?.dataset.historyDelete;if(deleteId){safeStorageSet(STORAGE_KEYS.history,getAnalysisHistory().filter(x=>x.id!==deleteId));renderHistory();updateHistoryBadge();return}if(!profileId)return;const item=getAnalysisHistory().find(x=>x.id===profileId);if(!item)return;applySelectionIds(item.selectionIds);closeHistory();toast('Profil iz povijesti je učitan.')}
