function renderSubmissionGate(r){const el=$('#submissionGate');if(!el)return;const a=submissionAssessment(r),text=a.overall==='ready'?'Svi automatizirani uvjeti prolaze i ručne obveze su potvrđene.':a.overall==='conditional'?'Dokument ili datoteke nemaju blokirajuću pogrešku, ali ostaju ručne ili neizvjesne stavke.':'Postoji barem jedan blokirajući problem u dokumentu ili paketu datoteka.';el.innerHTML=`<div class="gate-hero ${a.overall}"><div><h3>${statusLabel(a.overall)} ZA PREDAJU</h3><p>${escapeHtml(text)}</p></div><span class="gate-badge">Faza: ${escapeHtml(({document:'dokument',before:'prije obrane',after:'nakon obrane',full:'cijeli paket'})[a.blueprint.phase])}</span></div><div class="gate-grid"><article class="gate-card ${a.document.status}"><span>Dokument</span><b>${statusLabel(a.document.status)}</b><small>${a.document.errors?`${a.document.errors} kritičnih upozorenja`:'bez kritičnih upozorenja'}</small></article><article class="gate-card ${a.files.status}"><span>Datoteke</span><b>${statusLabel(a.files.status)}</b><small>${a.files.blockers.length?`${a.files.blockers.length} blokirajućih stavki`:a.files.warnings.length?`${a.files.warnings.length} neizvjesnih stavki`:'paket datoteka prolazi'}</small></article><article class="gate-card ${a.procedure.status}"><span>Postupak</span><b>${statusLabel(a.procedure.status)}</b><small>${a.procedure.incomplete.length?`${a.procedure.incomplete.length} nepotvrđenih obveza`:'sve ručno potvrđeno'}</small></article></div>`;return a}
