function motionReduced(){return !!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches)}
function _animate(){return window.__lektaAnimate} // lijeno ucitan Motion (ui-boot); null dok se ne ucita
function countUp(el,to,fmtFn){if(!el)return;const target=Number(to);if(!isFinite(target)){el.textContent=to;return}const out=v=>{const n=Math.round(v);el.textContent=fmtFn?fmtFn(n):String(n)};const A=_animate();if(motionReduced()||typeof A!=='function'){out(target);return}A(0,target,{duration:.9,ease:[.22,1,.36,1],onUpdate:out})}
function animateScore(ring,valueEl,score){countUp(valueEl,score==null?'—':score);if(!ring)return;const s=Number(score),A=_animate();if(!isFinite(s)||motionReduced()||typeof A!=='function'){ring.style.setProperty('--score',isFinite(s)?s:0);return}A(ring,{'--score':[0,s]},{duration:.95,ease:[.22,1,.36,1]})}
function animateBars(){const A=_animate();document.querySelectorAll('#categoryGrid .bar > i').forEach(el=>{const p=Number(el.dataset.fill)||0;if(motionReduced()||typeof A!=='function'){el.style.width=p+'%';return}A(el,{width:['0%',p+'%']},{duration:.8,ease:[.22,1,.36,1],delay:.12})})}
