function buildStandaloneReport(r){const status=PROFILE_STATUS[r.profileStatus]||PROFILE_STATUS.generic,authority=PROFILE_AUTHORITY[r.details?.ruleAuthority]||PROFILE_AUTHORITY.generic,sub=r.submission,subHtml=sub?`<h2>Spremnost za predaju</h2><section class="hero"><h3>${escapeHtml(statusLabel(sub.overall))}</h3><div class="grid"><div class="box"><span>Dokument</span><b>${escapeHtml(statusLabel(sub.document.status))}</b></div><div class="box"><span>Datoteke</span><b>${escapeHtml(statusLabel(sub.files.status))}</b></div><div class="box"><span>Postupak</span><b>${escapeHtml(statusLabel(sub.procedure.status))}</b></div><div class="box"><span>Faza</span><b>${escapeHtml(sub.blueprint.phase)}</b></div></div>${sub.blueprint.selectedDeadline?`<p><strong>Odabrani godišnji rok:</strong> ${escapeHtml(sub.blueprint.selectedDeadline.label)} · ${escapeHtml(dateRange(sub.blueprint.selectedDeadline.defenseStart||sub.blueprint.selectedDeadline.start,sub.blueprint.selectedDeadline.defenseEnd||sub.blueprint.selectedDeadline.end))}</p>`:''}${sub.files.blockers?.length?`<p><strong>Blokira:</strong> ${escapeHtml(sub.files.blockers.join(' · '))}</p>`:''}${sub.procedure.incomplete?.length?`<p><strong>Nepotvrđeno:</strong> ${escapeHtml(sub.procedure.incomplete.map(x=>x.label).join(' · '))}</p>`:''}</section>`:'';const checkRows=(r.checks||[]).map(c=>`<tr><td>${escapeHtml(c.title)}</td><td>${c.max===0?'Informativno':c.status==='pass'?'U redu':c.status==='fail'?'Važno':'Provjeri'}</td><td>${escapeHtml(c.detail)}</td><td>${c.max===0?'—':`${Math.round(c.earned*10)/10}/${c.max}`}</td></tr>`).join('');const issueRows=(r.issues||[]).map(i=>`<article class="issue ${i.severity}"><h3>${escapeHtml(i.title)}</h3><p>${escapeHtml(i.detail)}</p><small>${escapeHtml(i.where||i.category)}</small></article>`).join('')||'<p>Nema prijavljenih problema.</p>';const sourceRows=(r.details?.sources||[]).map(x=>`<li><a href="${escapeHtml(safeHref(x.url))}">${escapeHtml(x.title)}</a></li>`).join('');return`<!doctype html><html lang="hr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Lekta izvještaj — ${escapeHtml(r.file.name)}</title><style>body{font:15px/1.55 Arial,sans-serif;color:#172033;max-width:1050px;margin:40px auto;padding:0 24px}h1{font-size:30px;margin-bottom:4px}.muted{color:#667085}.hero{border:1px solid #dfe4ee;border-radius:18px;padding:22px;margin:22px 0}.score{font-size:42px;font-weight:800}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.box{border:1px solid #dfe4ee;border-radius:12px;padding:12px}.box span{display:block;color:#667085;font-size:11px}.box b{font-size:19px}table{width:100%;border-collapse:collapse;margin:16px 0}th,td{text-align:left;border-bottom:1px solid #dfe4ee;padding:9px;vertical-align:top}th{font-size:11px;color:#667085}.issue{border-left:4px solid #d08b00;padding:10px 13px;margin:9px 0;background:#fafafa}.issue.error{border-color:#c9364f}.issue.info{border-color:#246fb8}.issue h3{font-size:14px;margin:0}.issue p{margin:4px 0}.issue small{color:#667085}.note{padding:12px;background:#eef2ff;border-radius:10px}.wm-banner{padding:12px;background:#fff7e6;border:1px solid #ecd9a8;border-radius:10px;margin:14px 0;font-weight:600}.wm-diag{position:fixed;top:42%;left:50%;transform:translate(-50%,-50%) rotate(-28deg);font-size:64px;font-weight:800;color:rgba(23,32,51,.08);white-space:nowrap;pointer-events:none;z-index:0}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}</style></head><body>${r.watermark?'<div class="wm-diag" aria-hidden="true">LEKTA · BESPLATNI SAŽETAK</div>':''}<h1>Lekta izvještaj</h1>${r.watermark?'<div class="wm-banner">Besplatni sažetak s vodenim žigom: prikazan je ograničen broj problema, bez detaljnih tablica provjera. Serverski potvrđen puni izvještaj je bez žiga.</div>':''}<p class="muted">Generirano ${escapeHtml(new Date(r.generatedAt).toLocaleString('hr-HR'))} · verzija ${escapeHtml(r.appVersion||APP_VERSION)}</p><section class="hero"><div class="score">${r.score??'—'}/100</div><h2>${escapeHtml(r.file.name)}</h2><p>${escapeHtml(r.profile)}</p>${r.details?.sources?.length?`<p class="muted"><strong>Provjereno prema:</strong> <a href="${escapeHtml(safeHref(r.details.sources[0].url))}">${escapeHtml(r.details.sources[0].title)}</a>${(r.details.documentDate||r.details.verifiedAt)?' ('+escapeHtml(r.details.documentDate||r.details.verifiedAt)+')':''}</p>`:''}<p class="muted">${escapeHtml(status.label)} · ${escapeHtml(authority.label)} · ${escapeHtml(r.details?.profileFingerprint||'bez otiska')}</p><div class="grid"><div class="box"><span>Problemi</span><b>${r.issueTotal??(r.issues?.length||0)}</b></div><div class="box"><span>Riječi</span><b>${fmt(r.stats?.officialWords||r.stats?.words)}</b></div><div class="box"><span>Izvori</span><b>${fmt(r.stats?.references)}</b></div><div class="box"><span>Citatnice</span><b>${fmt(r.stats?.citations)}</b></div></div></section><p class="note">Izvještaj ne sadrži tekst dokumenta. Rezultat je pomoćna tehnička provjera i ne zamjenjuje službene upute ni odluku mentora.</p>${subHtml}${r.watermark&&!checkRows?'<h2>Automatske provjere</h2><p class="note">Detaljne tablice provjera dio su punog izvještaja.</p>':`<h2>Automatske provjere</h2><table><thead><tr><th>Provjera</th><th>Status</th><th>Rezultat</th><th>Bodovi</th></tr></thead><tbody>${checkRows}</tbody></table>`}<h2>Pronađeni problemi</h2>${issueRows}${sourceRows?`<h2>Izvori profila</h2><ul>${sourceRows}</ul>`:''}</body></html>`}
function downloadHtmlReport(){if(!currentResult)return;const exportResult=structuredClone(currentResult);exportResult.submission=submissionAssessment(currentResult);exportResult.details.pdfPreflight=currentPdfAudit;exportResult.details.metadataDocument=currentMetadataAudit;if(paywallGateActive()){exportResult.watermark=true;exportResult.issueTotal=(exportResult.issues||[]).length;exportResult.checks=[];exportResult.issues=(exportResult.issues||[]).slice(0,TEASER_SAMPLE)}downloadBlob(buildStandaloneReport(exportResult),'text/html;charset=utf-8',`Lekta-izvjestaj-${currentResult.file.name.replace(/\.docx$/i,'')}.html`);trackEvent('report_downloaded',{source:paywallGateActive()?'html-teaser':'html',profileId:currentResult.details?.profileDefinitionId||''})}
function profileManifest(){const coverage=coverageSnapshot();return{appVersion:APP_VERSION,generatedAt:new Date().toISOString(),coverage:{verifiedAt:INSTITUTIONAL_COVERAGE_MATRIX.verifiedAt,summary:coverage.counts,programs:coverage.rows.map(x=>({id:x.id,unitId:x.unitId,name:x.name,level:x.level,scope:x.scope,expectedWorkTypes:x.expectedWorkTypes,status:x.evaluation.status,gaps:x.evaluation.gaps,profileIds:x.evaluation.profiles.map(p=>p.id),source:x.source}))},profiles:VERIFIED_PROFILE_REGISTRY.map(p=>({id:p.id,unitId:p.unitId,programs:p.programs,workTypes:p.workTypes,status:p.status,variant:p.variant||null,verifiedAt:p.verifiedAt||null,ruleAuthority:p.ruleAuthority||null,sources:(p.sources||[]).map(x=>x.url)})),departments:LEGAL_DEPARTMENT_REGISTRY.map(d=>({id:d.id,name:d.name,programs:d.programs,workTypes:d.workTypes,status:d.status,ruleAuthority:d.ruleAuthority,sources:(d.sources||[]).map(x=>x.url)}))}}
function runRegistryDiagnostics(){const rows=[],add=(level,title,detail)=>rows.push({level,title,detail});const profileIds=VERIFIED_PROFILE_REGISTRY.map(x=>x.id),departmentIds=LEGAL_DEPARTMENT_REGISTRY.map(x=>x.id),unitMap=new Map(allUnits().map(x=>[x.id,x]));for(const [label,ids]of [['Profil',profileIds],['Katedarski profil',departmentIds]]){const dup=[...new Set(ids.filter((x,i)=>ids.indexOf(x)!==i))];add(dup.length?'fail':'pass',`${label}: jedinstveni ID-jevi`,dup.length?`Duplikati: ${dup.join(', ')}`:`${ids.length} jedinstvenih zapisa`)}for(const p of VERIFIED_PROFILE_REGISTRY){const unit=unitMap.get(p.unitId);if(!unit){add('fail',p.id,`Nepostojeći unitId: ${p.unitId}`);continue}const missingPrograms=(p.programs||[]).filter(x=>!unit.programs.includes(x));if(missingPrograms.length)add('fail',p.id,`Program nije u katalogu: ${missingPrograms.join(', ')}`);const badTypes=(p.workTypes||[]).filter(x=>!VALID_WORK_TYPES.has(x));if(badTypes.length)add('fail',p.id,`Nepoznata vrsta rada: ${badTypes.join(', ')}`);if(!p.rules||typeof p.rules!=='object')add('fail',p.id,'Nedostaje rules objekt');const badSources=(p.sources||[]).filter(x=>!/^https:\/\//.test(x.url||''));if(badSources.length)add('warn',p.id,`${badSources.length} izvora nije HTTPS`);const citation=p.rules?.recommendedCitation;if(citation&&!VALID_CITATION_IDS.has(citation))add('fail',p.id,`Nepoznat citatni profil: ${citation}`)}const pravo=unitMap.get('pravo');for(const d of LEGAL_DEPARTMENT_REGISTRY){const missing=(d.programs||[]).filter(x=>!pravo?.programs.includes(x));if(missing.length)add('fail',d.id,`Program nije u katalogu Pravnog fakulteta: ${missing.join(', ')}`);const bad=(d.workTypes||[]).filter(x=>!VALID_WORK_TYPES.has(x));if(bad.length)add('fail',d.id,`Nepoznata vrsta rada: ${bad.join(', ')}`);if(!(d.sources||[]).length)add('warn',d.id,'Nema službenog izvora')}const coveredFpzg=['fpzg-politologija-zavrsni','fpzg-novinarstvo-zavrsni-tekst','fpzg-novinarstvo-zavrsni-av','fpzg-politologija-diplomski','fpzg-nacionalna-sigurnost-diplomski','fpzg-novinarstvo-diplomski'];const missingFpzg=coveredFpzg.filter(id=>!VERIFIED_PROFILE_REGISTRY.some(p=>p.id===id));add(missingFpzg.length?'fail':'pass','FPZG v2.2.2 predajni profili',missingFpzg.length?`Nedostaju: ${missingFpzg.join(', ')}`:'6/6 odvojenih profila povezano s godišnjim kalendarom 2025./2026.');const matrixRows=coverageSnapshot().rows,matrixIds=matrixRows.map(x=>x.id),matrixDup=[...new Set(matrixIds.filter((x,i)=>matrixIds.indexOf(x)!==i))];add(matrixDup.length?'fail':'pass','Institucionalna matrica: jedinstveni ID-jevi',matrixDup.length?`Duplikati: ${matrixDup.join(', ')}`:`${matrixIds.length} jedinstvenih programa`);for(const unitId of ['fpzg','pravo']){const unit=unitMap.get(unitId),matrixPrograms=matrixRows.filter(x=>x.unitId===unitId).map(x=>x.name),catalogPrograms=(unit?.programs||[]).filter(x=>!/^Opći/.test(x));const absent=matrixPrograms.filter(x=>!catalogPrograms.includes(x)),unmapped=catalogPrograms.filter(x=>!matrixPrograms.includes(x));add(absent.length||unmapped.length?'fail':'pass',`${unitId.toUpperCase()}: katalog ↔ matrica`,absent.length||unmapped.length?`Nema u katalogu: ${absent.join(', ')||'—'}; nema u matrici: ${unmapped.join(', ')||'—'}`:`${matrixPrograms.length} programa u potpunosti mapirano`)}const matrixGaps=matrixRows.filter(x=>['missing','partial','published'].includes(x.evaluation.status));add(matrixGaps.length?'warn':'pass','Preostali razvojni jaz',matrixGaps.length?`${matrixGaps.length} internih programa još nije na statusu potpune spremnosti.`:'Svi interni programi imaju potpuni profil.');const externalRows=matrixRows.filter(x=>x.evaluation.status==='external');add('pass','Partnerski i združeni programi',`${externalRows.length} programa odvojeno označeno kao vanjsko upravljanje pravilima.`);const ps=productionStatus();add(ps.active?'pass':'warn','Produkcijska predaja',ps.active?`Aktivna: ${ps.endpoint}`:'Nije aktivirana; koristi se lokalni fallback.');add(ps.links===PACKAGES.length?'pass':'warn','Payment linkovi',`${ps.links}/${PACKAGES.length} paketa ima konfiguriran checkout.`);add(productionConfig.contactEmail?'pass':'warn','Kontakt privatnosti',productionConfig.contactEmail||'Kontakt e-mail nije konfiguriran.');if(productionConfig.analyticsEndpoint)add(safeStorageGet(STORAGE_KEYS.analyticsConsent)?'pass':'warn','Klijentska analitika','Endpoint postoji; privola se prikuplja u sučelju.');else add('pass','Klijentska analitika','Nije uključena; nema klijentskog praćenja.');if(!rows.some(x=>x.level==='fail'))add('pass','Usmjeravanje profila','Nisu pronađene blokirajuće pogreške u registrima.');return rows}
function openQa(){const rows=runRegistryDiagnostics(),pass=rows.filter(x=>x.level==='pass').length,warn=rows.filter(x=>x.level==='warn').length,fail=rows.filter(x=>x.level==='fail').length,cov=coverageSnapshot().counts;$('#qaResults').innerHTML=`<div class="qa-summary"><div class="qa-stat"><span>PROGRAMI</span><b>${cov.total}</b></div><div class="qa-stat"><span>SPREMNO</span><b>${cov.ready}</b></div><div class="qa-stat"><span>PROFILI</span><b>${VERIFIED_PROFILE_REGISTRY.length}</b></div><div class="qa-stat"><span>UPOZORENJA</span><b>${warn}</b></div><div class="qa-stat"><span>POGREŠKE</span><b>${fail}</b></div></div><div class="qa-list">${rows.map(x=>`<div class="qa-row ${x.level}"><span>${x.level==='pass'?'<i data-lucide="check-circle"></i>':x.level==='fail'?'<i data-lucide="alert-circle"></i>':'<i data-lucide="alert-triangle"></i>'}</span><div><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p></div></div>`).join('')}</div><p class="profile-note"><strong>Rezultat:</strong> ${pass} prolaznih provjera, ${warn} upozorenja i ${fail} blokirajućih pogrešaka. QA konzola provjerava strukturu registra, ne sadržaj službenih dokumenata.</p>`;window.__lektaIcons?.();$('#qaModal').classList.remove('hidden');trapModal($('#qaModal'))}
function closeQa(){$('#qaModal')?.classList.add('hidden');releaseModal($('#qaModal'))}
function downloadProfileManifest(){downloadBlob(JSON.stringify(profileManifest(),null,2),'application/json',`Lekta-profile-manifest-v${APP_VERSION}.json`)}
function reportEndpointConfigured(){return!!String(productionConfig?.reportEndpoint||'').trim()}
function eurLabel(n){return`${Number(n).toFixed(2).replace('.',',')} €`}
// Teaser/full granica (buildTeaser semantika u zivom UI-u). Aktivna SAMO kad je paywall
// konfiguriran (reportEndpoint) i rezultat jos nije otkljucan; bez konfiguracije aplikacija
// ostaje potpuno besplatna kao dosad. Granica je proizvodna, ne DRM: sav izracun je lokalan.
const TEASER_SAMPLE=2;
function paywallGateActive(){return reportEndpointConfigured()&&!!currentResult&&!currentResult.fullReport}
function doObraneProduct(workType){if(!_retailCatalog)return null;return _retailCatalog.find(x=>x.id===`slot_${workType}_do_obrane`&&x.kind==='slot'&&x.audience==='retail'&&x.active)||null}
function paywallLockHtml(what){const wt=toReportWorkType(currentResult?.settings?.workType||'final'),tier=tierFor(wt),price=tier?(livePriceEur(tier.workType)??tier.priceEur):null,ob=checkoutConfigured()?doObraneProduct(wt):null;return`<div class="lock-panel"><i data-lucide="lock" aria-hidden="true"></i><div><strong>${escapeHtml(what)}</strong><p>Dio punog izvještaja: serverski potvrđen, bez vodenog žiga${tier?`, ${escapeHtml(tier.label.toLowerCase())} ${eurLabel(price)}`:''}, uz besplatne ponovne provjere istog rada unutar prozora. Pri otključavanju se poslužitelju šalju parsirana struktura i rezultat analize; sam dokument ostaje na uređaju.</p><button class="btn btn-primary btn-sm" type="button" data-unlock-cta>Otključaj puni izvještaj</button>${ob?` <button class="btn btn-secondary btn-sm" type="button" data-buy-obrana="${escapeHtml(wt)}">Do obrane: ${ob.slotWindowDays} dana ponovnih provjera · ${eurLabel(ob.priceEur)}</button>`:''}</div></div>`}
function wireLockCtas(){$$('[data-unlock-cta]').forEach(b=>{b.onclick=handleUnlockReport});$$('[data-buy-obrana]').forEach(b=>{b.onclick=()=>startReportCheckout(b.dataset.buyObrana,'do_obrane')});window.__lektaIcons?.()}
const SESSION_KEY='lekta.session';
const authStore={load:()=>safeStorageGet(SESSION_KEY,null),save:s=>safeStorageSet(SESSION_KEY,s)};
function authConfig(){return{supabaseUrl:String(productionConfig?.supabaseUrl||'').trim(),anonKey:String(productionConfig?.supabaseAnonKey||'').trim()}}
function authConfigured(){const c=authConfig();return!!(c.supabaseUrl&&c.anonKey)}
// Valjan pristupni token: iz Supabase sesije ako je auth konfiguriran (null -> pozivatelj otvara prijavu),
// inace legacy reportToken (nekonfigurirano okruzenje se ponasa kao dosad).
async function resolveAccessToken(){if(authConfigured()){try{return await getValidAccessToken(authConfig(),authStore)}catch(e){return null}}return String(productionConfig?.reportToken||'')}
let _authEmail='',_authStep='email',_pendingAuthAction=null;
function setAuthStatus(type,msg){const st=$('#authStatus');if(!st)return;if(!msg){st.className='order-status hidden';st.textContent='';return}st.className=`order-status ${type}`;st.textContent=msg}
function resetAuthModal(){_authEmail='';_authStep='email';const em=$('#authEmail'),cc=$('#authCode');if(em){em.value='';em.disabled=false}if(cc)cc.value='';$('#authCodeField')?.classList.add('hidden');$('#authChangeEmail')?.classList.add('hidden');const sub=$('#authSubmit');if(sub){sub.textContent='Pošalji kod';sub.disabled=false}setAuthStatus('','')}
function openAuth(afterSignIn){_pendingAuthAction=afterSignIn||null;resetAuthModal();$('#authModal')?.classList.remove('hidden');trapModal($('#authModal'));setTimeout(()=>$('#authEmail')?.focus(),40)}
function closeAuth(){$('#authModal')?.classList.add('hidden');releaseModal($('#authModal'))}
async function authSubmit(){const sub=$('#authSubmit');if(!sub)return;if(sub.disabled)return;if(_authStep==='email'){const email=($('#authEmail')?.value||'').trim();sub.disabled=true;setAuthStatus('pending','Šaljem kod…');const out=await requestEmailOtp(authConfig(),email);sub.disabled=false;if(out.ok){_authEmail=email;_authStep='code';const em=$('#authEmail');if(em)em.disabled=true;$('#authCodeField')?.classList.remove('hidden');$('#authChangeEmail')?.classList.remove('hidden');sub.textContent='Potvrdi kod';setAuthStatus('success',`Kod je poslan na ${email}. Provjeri i mapu neželjene pošte.`);setTimeout(()=>$('#authCode')?.focus(),40)}else{setAuthStatus('error',out.message||'Slanje koda nije uspjelo.')}}else{const code=($('#authCode')?.value||'').trim();sub.disabled=true;setAuthStatus('pending','Provjeravam kod…');const out=await verifyEmailOtp(authConfig(),_authEmail,code);sub.disabled=false;if(out.ok){authStore.save(out.session);closeAuth();toast('Prijava uspješna.');trackEvent('auth_signed_in',{});const a=_pendingAuthAction;_pendingAuthAction=null;if(a)a()}else{setAuthStatus('error',out.message||'Kod nije točan.')}}}
function authChangeEmail(){_authStep='email';const em=$('#authEmail');if(em)em.disabled=false;const cc=$('#authCode');if(cc)cc.value='';$('#authCodeField')?.classList.add('hidden');$('#authChangeEmail')?.classList.add('hidden');const sub=$('#authSubmit');if(sub)sub.textContent='Pošalji kod';setAuthStatus('','');em?.focus()}
function checkoutConfigured(){return!!String(productionConfig?.checkoutEndpoint||'').trim()}
// Garancijski zahtjev (file-guarantee-claim Edge Function). Pokriva TOCNOST verificiranih
// bodovanih pravila (T2/T3, 30 dana od vezivanja), NE prihvacanje rada; odluka je rucna.
// "Dokaz" se u ovoj verziji salje kao tekstualni opis/poveznica u evidencePath (bez
// zasebnog storage uploada); admin ga cita pri rucnoj odluci.
function guaranteeConfigured(){return!!String(productionConfig?.guaranteeEndpoint||'').trim()}
function guaranteeEligible(){const fr=currentResult?.fullReport;return!!(fr&&Number(fr.coverageTier)>=2&&currentResult.fullReportSlotId&&guaranteeConfigured())}
function setGuaranteeStatus(type,msg){const st=$('#guaranteeStatus');if(!st)return;if(!msg){st.className='order-status hidden';st.textContent='';return}st.className=`order-status ${type}`;st.textContent=msg}
function openGuarantee(){if(!guaranteeEligible())return;const sel=$('#guaranteeRule');if(sel){const checks=(currentResult.fullReport.checks||[]).filter(c=>c&&c.confidence&&c.confidence!=='informational'&&c.status==='pass');sel.innerHTML=checks.length?checks.map(c=>`<option value="${escapeHtml(c.title)}">${escapeHtml(c.title)}</option>`).join(''):'<option value="">Nema bodovanih pravila označenih prolaznim</option>'}const ev=$('#guaranteeEvidence');if(ev)ev.value='';setGuaranteeStatus('','');$('#guaranteeModal')?.classList.remove('hidden');trapModal($('#guaranteeModal'))}
function closeGuarantee(){$('#guaranteeModal')?.classList.add('hidden');releaseModal($('#guaranteeModal'))}
async function submitGuaranteeClaim(){if(!guaranteeEligible()){setGuaranteeStatus('error','Garancija vrijedi samo uz otključan puni izvještaj verificiranog (T2/T3) profila.');return}const ruleKey=($('#guaranteeRule')?.value||'').trim(),evidence=($('#guaranteeEvidence')?.value||'').trim();if(!ruleKey){setGuaranteeStatus('error','Odaberi sporno pravilo.');return}if(evidence.length<20){setGuaranteeStatus('error','Opiši dokaz (povrat referade) u barem jednoj rečenici, po mogućnosti s poveznicom.');return}const token=await resolveAccessToken();if(authConfigured()&&!token){openAuth(()=>submitGuaranteeClaim());return}const btn=$('#guaranteeSubmit');if(btn)btn.disabled=true;setGuaranteeStatus('pending','Šaljem zahtjev…');try{const res=await fetch(String(productionConfig.guaranteeEndpoint).trim(),{method:'POST',headers:{'content-type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},body:JSON.stringify({slotId:currentResult.fullReportSlotId,ruleKey,evidencePath:evidence})});const data=await res.json().catch(()=>({}));if(res.ok&&data.ok){setGuaranteeStatus('success',`Zahtjev ${data.claimId?String(data.claimId).slice(0,8):''} je zaprimljen (status: na čekanju). Odluku donosi čovjek nakon pregleda dokaza; odgovor stiže e-mailom.`);trackEvent('guarantee_claim_filed',{})}else{const reason=String(data.error||'');const msgs={tier_too_low:'Garancija vrijedi samo za verificirane (T2/T3) profile.',window_expired:'Prošlo je više od 30 dana od vezivanja izvještaja.',missing_evidence:'Nedostaje opis dokaza.',missing_rule_key:'Nedostaje sporno pravilo.',slot_not_found:'Pripadajući izvještaj nije pronađen na ovom računu.',unauthorized:'Za zahtjev je potrebna prijava.'};setGuaranteeStatus('error',msgs[reason]||'Zahtjev trenutačno nije moguće poslati.')}}catch(e){setGuaranteeStatus('error','Mrežna pogreška pri slanju zahtjeva.')}finally{if(btn)btn.disabled=false}}
function resetUnlockButton(){const ub=$('#unlockReport');if(!ub)return;ub.textContent='Otključaj puni izvještaj';ub.onclick=handleUnlockReport;ub.disabled=false;ub.classList.toggle('hidden',!reportEndpointConfigured())}
// Klijentski checkout: salje samo productId (kriterij 14.1). Bez Supabase JWT-a server
// vraca 401 pa se prikaze uputa za prijavu. Puni tok radi tek kad je backend spojen.
async function startReportCheckout(workType,variant){const base=slotProductForWorkType(workType),productId=variant==='do_obrane'&&base?`${base}_do_obrane`:base;if(!productId){toast('Za ovu vrstu rada checkout nije dostupan.');return}const token=await resolveAccessToken();if(authConfigured()&&!token){openAuth(()=>startReportCheckout(workType));return}const ub=$('#unlockReport');if(ub)ub.disabled=true;toast('Otvaram sigurno plaćanje…');try{const out=await createCheckout({endpoint:String(productionConfig.checkoutEndpoint).trim()},token,productId);if(out.kind==='ok'){trackEvent('checkout_started',{product:productId});location.href=out.checkoutUrl;return}if(out.kind==='unauthorized')toast('Za kupnju paketa potrebna je prijava.');else if(out.kind==='forbidden')toast('Ovaj paket trenutačno nije dostupan.');else if(out.kind==='not_found')toast('Paket nije pronađen u katalogu.');else toast('Plaćanje trenutačno nije dostupno.')}catch(e){toast('Greška pri otvaranju plaćanja.')}finally{if(ub)ub.disabled=false}}
let _retailCatalog=null;
// Cijene iz products tablice (kriterij 14.2, "cijena bez deploya"): dohvat je lijeni i
// kesiran; paywall preferira zivu cijenu, a na bilo koji neuspjeh pada na WORK_TYPE_TIERS.
async function ensureRetailCatalog(force){if(_retailCatalog&&!force)return _retailCatalog;const supabaseUrl=String(productionConfig?.supabaseUrl||'').trim(),anonKey=String(productionConfig?.supabaseAnonKey||'').trim();if(!supabaseUrl||!anonKey)return null;try{_retailCatalog=await fetchRetailCatalog({supabaseUrl,anonKey})}catch(e){_retailCatalog=null}return _retailCatalog}
function livePriceEur(workType){if(!_retailCatalog)return null;const p=_retailCatalog.find(x=>x.kind==='slot'&&x.audience==='retail'&&x.active&&x.workType===workType);return p&&isFinite(p.priceEur)?p.priceEur:null}
function showPaywall(workType){const tier=tierFor(workType),price=tier?(livePriceEur(tier.workType)??tier.priceEur):0,label=tier?`${tier.label} (${eurLabel(price)})`:workType,ub=$('#unlockReport');if(checkoutConfigured()&&tier&&ub){ub.classList.remove('hidden');ub.disabled=false;ub.textContent=`Kupi paket: ${tier.label} · ${eurLabel(price)} →`;ub.onclick=()=>startReportCheckout(tier.workType);toast(`Za puni izvještaj potreban je paket: ${label}.`)}else{toast(`Za puni izvještaj potreban je paket: ${label}.`);document.querySelector('#pricing')?.scrollIntoView({behavior:'smooth'})}}
async function handleUnlockReport(){if(!currentResult)return;if(!reportEndpointConfigured()){toast('Puni izvještaj nije konfiguriran u ovom okruženju.');return;}const ub=$('#unlockReport');if(ub)ub.disabled=true;const token=await resolveAccessToken();if(authConfigured()&&!token){if(ub)ub.disabled=false;openAuth(()=>handleUnlockReport());return}try{const cfg={endpoint:String(productionConfig.reportEndpoint).trim()},workType=currentResult.settings?.workType||$('#workType')?.value||'final';const out=await unlockReportRequest(currentResult,workType,cfg,token);if(out.kind==='ok'){currentResult.fullReport=out.report;currentResult.fullReportSlotId=out.slotId||null;renderResult(currentResult);toast('Puni izvještaj je otključan.');trackEvent('full_report_unlocked',{profileId:currentResult.details?.profileDefinitionId||''})}else if(out.kind==='paywall'){showPaywall(out.workType)}else if(out.kind==='unauthorized'){toast('Prijava je potrebna za puni izvještaj.')}else if(out.kind==='rate_limited'){toast('Previše zahtjeva u kratko vrijeme. Pokušaj kasnije.')}else{toast('Puni izvještaj trenutačno nije dostupan.')}}catch(e){toast('Greška pri otključavanju izvještaja.')}finally{if(ub)ub.disabled=false}}
// Prikaz punog izvjestaja: banner se pojavi tek kad server vrati fullReport (coverageTier +
// traceToken). Do tada je skriven; teaser rezultat ostaje potpuno lokalan i besplatan.
function renderFullReportBanner(r){const el=$('#fullReportBanner');if(!el)return;const fr=r&&r.fullReport;if(!fr){el.classList.add('hidden');el.innerHTML='';return}const tier=Number(fr.coverageTier)||0,labels=['Osnovna pokrivenost','Proširena pokrivenost','Verificirana pokrivenost (garancija)','Potpuna pokrivenost (garancija)'],tierLabel=labels[tier]||`Razina ${tier}`,token=fr.traceToken?`<span class="frb-token">trag: ${escapeHtml(String(fr.traceToken))}</span>`:'';const checks=Array.isArray(fr.checks)?fr.checks:[],cnt=k=>checks.filter(c=>c&&c.confidence===k).length,scored=typeof fr.scoredCount==='number'?fr.scoredCount:checks.length-cnt('informational'),unver=typeof fr.unverifiedCount==='number'?fr.unverifiedCount:cnt('informational'),high=cnt('high'),med=cnt('medium'),low=cnt('low'),conf=`<span class="frb-conf">Bodovano: ${scored}${high||med||low?` (visoka ${high}, srednja ${med}, niska ${low})`:''}</span><span class="frb-conf frb-unver">Nepotvrđeno: ${unver}</span>`;el.classList.remove('hidden');const guaranteeBtn=guaranteeEligible()?`<button class="btn btn-secondary btn-sm" type="button" id="guaranteeOpen">Garancija točnosti (T2/T3) →</button>`:'';el.innerHTML=`<span class="frb-title"><i data-lucide="badge-check"></i> Puni izvještaj otključan</span><span class="frb-tier">${escapeHtml(tierLabel)}</span>${conf}${token}${guaranteeBtn}<p class="frb-note">Bodovana pravila nose oznaku pouzdanosti prema statusu profila; nepotvrđene stavke prikazuju se informativno i ne ulaze u ocjenu. Puni izvještaj je serverski potvrđen i bez vodenog žiga.${guaranteeEligible()?' Garancija pokriva točnost verificiranih bodovanih pravila, ne prihvaćanje rada.':''}</p>`;const _gb=$('#guaranteeOpen');if(_gb)_gb.onclick=openGuarantee;window.__lektaIcons?.()}
