function openOrder(id='format',brief){currentPackage=id;$$('input[name="package"]').forEach(r=>r.checked=r.value===id);clearOrderStatus();$('#orderConsent').checked=false;renderProductionState();updateOrderFileMeta();const _notes=$('#orderNotes');if(brief&&_notes&&!_notes.value.trim())_notes.value=brief;$('#orderModal').classList.remove('hidden');trapModal($('#orderModal'));trackEvent('order_opened',{package:id,provider:productionConfig.paymentProvider});setTimeout(()=>$('#orderName').focus(),50)}function closeOrder(){$('#orderModal').classList.add('hidden');releaseModal($('#orderModal'))}
async function submitOrder(){const name=$('#orderName').value.trim(),email=$('#orderEmail').value.trim(),pkg=$('input[name="package"]:checked')?.value,file=selectedOrderFile(),consent=$('#orderConsent').checked;if(!name||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Upiši ime i valjanu e-mail adresu.');return}if(!consent){toast('Za slanje narudžbe potrebno je prihvatiti uvjete i obavijest o privatnosti.');return}if(file&&(!file.name.toLowerCase().endsWith('.docx')||file.size>productionConfig.uploadMaxBytes)){setOrderStatus('error',`Dokument mora biti .docx i ne smije biti veći od ${Math.round(productionConfig.uploadMaxBytes/1024/1024)} MB. Narudžbu možeš poslati bez datoteke i naknadno dogovoriti drugi siguran kanal.`);return}const orderId=makeOrderId(),profile=currentProfile().p,order={orderId,createdAt:new Date().toISOString(),customer:{name,email},package:PACKAGES.find(p=>p.id===pkg),deadline:$('#orderDeadline').value||null,notes:$('#orderNotes').value.trim(),marketingConsent:$('#orderMarketing').checked,termsVersion:TERMS_VERSION,document:file?{name:file.name,size:file.size,type:file.type}:null,analysis:currentResult?{file:currentResult.file.name,score:currentResult.score,profile:currentResult.profile,profileStatus:currentResult.profileStatus,fingerprint:currentResult.profileFingerprint||null,selection:currentResult.selection}:null,requestedProfile:profile.selection,status:'PENDING'};trackEvent('order_submit_attempt',{package:pkg,profileId:profile.definitionId||profile.id,workType:profile.selection.workType,provider:productionConfig.paymentProvider});const button=$('#submitOrder');button.disabled=true;button.textContent='Šaljem…';setOrderStatus('pending','Pripremam sigurnu predaju narudžbe…');try{if(!productionStatus().active){order.status='LOCAL_DRAFT';downloadBlob(JSON.stringify(order,null,2),'application/json',`Lekta-narudzba-${orderId}.json`);saveOrderReceipt(order);setOrderStatus('success',`<strong>Testni zapis je izrađen.</strong> Narudžba ${escapeHtml(orderId)} nije poslana niti je dokument prenesen. Preuzeta je lokalna JSON datoteka za provjeru integracije.`);toast('Testna narudžba spremljena je lokalno.');return}const fd=new FormData();fd.append('form-name','lekta-orders');fd.append('order_id',orderId);fd.append('name',name);fd.append('email',email);fd.append('package',pkg);fd.append('deadline',order.deadline||'');fd.append('notes',order.notes);fd.append('profile',JSON.stringify(order.requestedProfile));fd.append('fingerprint',order.analysis?.fingerprint||'');fd.append('marketing_consent',String(order.marketingConsent));fd.append('terms_version',TERMS_VERSION);if(file)fd.append('document',file,file.name);const response=await fetch(productionConfig.orderEndpoint,{method:'POST',body:fd,headers:{Accept:'application/json, text/plain, */*'}});if(!response.ok)throw new Error(`HTTP ${response.status}`);order.status='RECEIVED';saveOrderReceipt(order);const payBase=productionConfig.paymentLinks?.[pkg]||'',payUrl=buildPaymentUrl(payBase,email,orderId,pkg),payment=payUrl?`<div class="payment-action"><a class="btn btn-primary btn-sm" id="paymentContinue" href="${escapeHtml(safeHref(payUrl))}" target="_blank" rel="noopener">Nastavi na sigurno plaćanje →</a></div>`:`<div class="payment-action"><strong>Plaćanje još nije povezano.</strong> Potvrda i upute bit će poslane na navedeni e-mail.</div>`;setOrderStatus('success',`<strong>Narudžba ${escapeHtml(orderId)} je zaprimljena.</strong> ${file?'Dokument je uključen u sigurnu predaju.':'Narudžba je zaprimljena bez dokumenta.'}${payment}`);trackEvent('order_submitted',{package:pkg,profileId:profile.definitionId||profile.id,provider:productionConfig.paymentProvider});setTimeout(()=>{const a=$('#paymentContinue');if(a)a.onclick=()=>trackEvent('payment_redirect',{package:pkg,provider:productionConfig.paymentProvider})},0)}catch(err){order.status='FAILED';setOrderStatus('error',`Narudžbu nije bilo moguće poslati (${escapeHtml(err.message||'mrežna pogreška')}). Dokument nije označen kao zaprimljen. Pokušaj ponovno ili kontaktiraj ${escapeHtml(productionConfig.contactEmail||'podršku nakon konfiguracije kontakta')}.`)}finally{button.disabled=false;button.textContent='Pošalji narudžbu'}}
if (typeof document !== 'undefined' && document.getElementById('analyzer')) init();
